/**
 * useDeviceGPS — Real Device GPS Mode for Trayago "Inside" feature.
 *
 * How it works:
 * 1. Calls navigator.geolocation.watchPosition() — browser/WebView GPS API.
 * 2. Updates every 5 seconds (maximumAge=5000, timeout=8000).
 * 3. Calculates instantaneous speed from haversine between last two positions.
 * 4. Exposes moving / stopped state (threshold: 5 km/h).
 * 5. No fake speed — if speed unavailable from native API, it is derived
 *    from delta-distance / delta-time between two real GPS fixes.
 *
 * Usage:
 *   const { position, speed, moving, error, permissionGranted } = useDeviceGPS();
 */
"use client";

import { useCallback, useEffect, useRef, useState } from "react";

export interface GPSPosition {
  lat: number;
  lon: number;
  accuracy: number;   // metres
  timestamp: number;  // epoch ms
}

export interface DeviceGPSState {
  position: GPSPosition | null;
  speed: number | null;           // km/h, null = not yet computed
  moving: boolean;                // true if speed >= MOVING_THRESHOLD_KMH
  heading: number | null;         // degrees, null if unavailable
  accuracy: number | null;        // metres accuracy
  maxSpeed: number;               // km/h top speed reached this session
  error: string | null;
  permissionGranted: boolean | null; // null = not asked yet
}

// Speed threshold for "moving" state (km/h)
const MOVING_THRESHOLD_KMH = 5;

// GPS options: poll frequently, high accuracy for train tracking
const GPS_OPTIONS: PositionOptions = {
  enableHighAccuracy: true,
  maximumAge: 5_000,   // accept cached fix up to 5s old for fast initial response
  timeout: 12_000,     // wait up to 12s for fix
};

function haversineKm(lat1: number, lon1: number, lat2: number, lon2: number): number {
  const R = 6371;
  const dLat = ((lat2 - lat1) * Math.PI) / 180;
  const dLon = ((lon2 - lon1) * Math.PI) / 180;
  const a =
    Math.sin(dLat / 2) ** 2 +
    Math.cos((lat1 * Math.PI) / 180) *
      Math.cos((lat2 * Math.PI) / 180) *
      Math.sin(dLon / 2) ** 2;
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}

export function useDeviceGPS(enabled: boolean = false): DeviceGPSState {
  const [state, setState] = useState<DeviceGPSState>({
    position: null,
    speed: null,
    moving: false,
    heading: null,
    accuracy: null,
    maxSpeed: 0,
    error: null,
    permissionGranted: null,
  });

  const prevPositionRef = useRef<GPSPosition | null>(null);
  const maxSpeedRef = useRef<number>(0);
  const watchIdRef = useRef<number | null>(null);

  const onSuccess = useCallback((pos: GeolocationPosition) => {
    const { latitude, longitude, accuracy, speed: nativeSpeed, heading } = pos.coords;
    const timestamp = pos.timestamp;

    const current: GPSPosition = { lat: latitude, lon: longitude, accuracy, timestamp };

    // Prefer native speed (m/s to km/h), else derive from delta-distance
    let speedKmh: number | null = null;
    
    // Some devices report 0 m/s even when moving. If 0 or null, try to derive from coords
    let derivedSpeed: number | null = null;
    if (prevPositionRef.current) {
      const prev = prevPositionRef.current;
      const distKm = haversineKm(prev.lat, prev.lon, latitude, longitude);
      const dtHours = (timestamp - prev.timestamp) / 3_600_000;
      if (dtHours > 0) derivedSpeed = distKm / dtHours;
    }

    if (nativeSpeed !== null && nativeSpeed > 0) {
      speedKmh = nativeSpeed * 3.6;
    } else if (nativeSpeed === 0) {
      speedKmh = 0;
    } else if (
      derivedSpeed !== null &&
      prevPositionRef.current &&
      (timestamp - prevPositionRef.current.timestamp) > 1200 &&
      accuracy <= 120
    ) {
      speedKmh = derivedSpeed;
    } else if (prevPositionRef.current === null) {
      // First GPS lock established: initialize baseline speed as 0 km/h (ready/platform)
      speedKmh = 0;
    }

    // Filter out platform jitter and impossible spikes
    if (speedKmh !== null) {
      if (speedKmh < 2.0) speedKmh = 0; // Standing at platform / stationary
      if (speedKmh > 180) speedKmh = null; // Unrealistic GPS glitch
    }

    const roundedSpeed = speedKmh !== null ? Math.round(speedKmh * 10) / 10 : null;
    if (roundedSpeed !== null && roundedSpeed > maxSpeedRef.current) {
      maxSpeedRef.current = Math.round(roundedSpeed);
    }

    prevPositionRef.current = current;

    setState({
      position: current,
      speed: roundedSpeed,
      moving: roundedSpeed !== null && roundedSpeed >= MOVING_THRESHOLD_KMH,
      heading: heading ?? null,
      accuracy: Math.round(accuracy),
      maxSpeed: maxSpeedRef.current,
      error: null,
      permissionGranted: true,
    });
  }, []);

  const onError = useCallback((err: GeolocationPositionError) => {
    let message = "GPS unavailable";
    if (err.code === err.PERMISSION_DENIED) message = "GPS permission denied. Enable location in device settings.";
    else if (err.code === err.POSITION_UNAVAILABLE) message = "GPS signal unavailable. Move near a train window.";
    else if (err.code === err.TIMEOUT) message = "GPS timed out: retrying...";

    setState((prev) => ({
      ...prev,
      error: message,
      permissionGranted: err.code !== err.PERMISSION_DENIED ? prev.permissionGranted : false,
    }));
  }, []);

  useEffect(() => {
    if (!enabled) return;

    if (!("geolocation" in navigator)) {
      setState((prev) => ({ ...prev, error: "Geolocation not supported on this device.", permissionGranted: false }));
      return;
    }

    // watchPosition fires whenever the device gets a new GPS fix (≥5 s cadence via maximumAge)
    watchIdRef.current = navigator.geolocation.watchPosition(onSuccess, onError, GPS_OPTIONS);

    return () => {
      if (watchIdRef.current !== null) {
        navigator.geolocation.clearWatch(watchIdRef.current);
        watchIdRef.current = null;
      }
    };
  }, [enabled, onSuccess, onError]);

  return state;
}
